    try {
      nextData = JSON.parse(script.textContent);
    } catch (e) {}
  }

  // Also extract details from the first article
  const firstArticle = document.querySelector('article');
  const allArticles = Array.from(document.querySelectorAll('article')).map(art => ({
    title: art.querySelector('h2')?.textContent?.trim() || art.querySelector('h3')?.textContent?.trim(),
    text: art.innerText,
    link: art.querySelector('a[href*="/details/"]')?.href || art.querySelector('a')?.href
  }));

  return {
    hasProps: !!nextData?.props,
    allArticlesCount: allArticles.length,
    firstArticle: allArticles[0],
    secondArticle: allArticles[1],
    thirdArticle: allArticles[2]
  };
});

